  getClanChatMessage(
    steamIDClanChat: bigint,
    iMessage: number,
    prgchText: Uint8Array,
    cchTextMax: number,
  ): { result: number; peChatEntryType: EChatEntryType; psteamidChatter: bigint } {
    const peChatEntryType_buf = scalarOut("i32");
    const psteamidChatter_buf = scalarOut("u64");
    const result = this.s.SteamAPI_ISteamFriends_GetClanChatMessage(
      this.self,
      steamIDClanChat,
      iMessage,
      prgchText,
      cchTextMax,
      peChatEntryType_buf,
      psteamidChatter_buf,
    );
    return {
      result,
      peChatEntryType: readScalar(peChatEntryType_buf, "i32") as EChatEntryType,
      psteamidChatter: readScalar(psteamidChatter_buf, "u64") as bigint,
    };
  }

